 "content": "def transform(grid):
    """Grow the inner color outward from the framed rectangle."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return out
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    outer = grid[r0][c0]
    other = {grid[r][c] for r, c in cells} - {outer}
    if len(other) != 1:
        return out
    inner = next(iter(other))
    marks = [(r, c) for r, c in cells if grid[r][c] == inner]
    ir0, ir1 = min(r for r, c in marks), max(r for r, c in marks)
    ic0, ic1 = min(c for r, c in marks), max(c for r, c in marks)
    ih, iw = ir1 - ir0 + 1, ic1 - ic0 + 1
    if ih == iw and ih > 1:
        expansion = ih
    elif ih == iw == 1:
        expansion = 1
    else:
        expansion = max(1, min(ir0-r0, r1-ir1, ic0-c0, c1-ic1))
    for r in range(max(0, r0-expansion), min(h, r1+expansion+1)):
        for c in range(max(0, c0-expansion), min(w, c1+expansion+1)):
            if out[r][c] == 0:
                out[r][c] = inner
    return out
